201	/** Every rule and question in file order, in the shape the review addresses: an edge under its rule, section = scenario title. */
202	export function specItems(spec: Spec): PlanItem[] {
203	  const items: PlanItem[] = []
204	  const cite = (item: Item): string => (item.citation ? `${item.text} (${item.citation})` : item.text)
205	  for (const scenario of spec.scenarios) {
206	    for (const behaviour of scenario.behaviours) {
207	      items.push({ name: behaviour.name, text: cite(behaviour), section: scenario.title, removed: behaviour.removed })
208	      for (const edge of behaviour.edges) items.push({ name: edge.name, text: cite(edge), section: scenario.title, removed: edge.removed })
209	    }
210	  }
211	  for (const question of spec.questions) {
212	    items.push({ name: question.name, text: cite(question), section: QUESTIONS_SECTION, removed: question.removed })
213	  }
214	  return items
215	}
