217	/** The scenario a rule sits in, for grouping tasks by what they deliver. */
218	export function scenarioOf(spec: Spec, name: string): Scenario | undefined {
219	  return spec.scenarios.find((s) => s.behaviours.some((b) => same(b.name, name) || b.edges.some((e) => same(e.name, name))))
220	}
