222	/** What the tasks were mapped from: the goal, the scenarios and the questions. */
223	export function specFingerprint(spec: Spec): string {
224	  const hash = createHash('sha1')
225	  hash.update(JSON.stringify({ goal: spec.goal, scenarios: spec.scenarios, questions: spec.questions }))
226	  return hash.digest('hex').slice(0, 8)
227	}
