229	/**
230	 * Tells the model, right after it wrote the spec, what does not fit the
231	 * contract. The file is already on disk, so the answer rides on the tool
232	 * result and the model fixes it in the same turn.
233	 */
234	export class SpecContract implements SessionHooks {
235	  constructor(private readonly cwd: string) {}
236	
237	  async postToolUse(tool: ToolUse & { output: string; isError: boolean }): Promise<PostToolUseOutcome> {
238	    if (tool.isError || (tool.toolName !== 'Write' && tool.toolName !== 'Edit')) return undefined
239	    const input = (typeof tool.input === 'object' && tool.input !== null ? tool.input : {}) as Record<string, unknown>
240	    const raw = input['file_path']
241	    if (typeof raw !== 'string') return undefined
242	    const path = isAbsolute(raw) ? raw : resolve(this.cwd, raw)
243	    const rel = relative(this.cwd, path).split('\\').join('/')
244	    if (!rel.startsWith(`${PLAN_DIR}/`) || !rel.endsWith('.spec.md')) return undefined
245	    const spec = parseSpecText(await readFile(path, 'utf8'))
246	    if (spec.problems.length === 0) return undefined
247	    return { additionalContext: contractProblems(rel, spec.problems) }
248	  }
249	}
250	
251	export function contractProblems(file: string, problems: string[]): string {
252	  return [
253	    `\`${file}\` is off contract. Fix it before you stop:`,
254	    ...problems.map((p) => `- ${p}`),
255	    '',
256	    `The contract: \`## ${GOAL_SECTION}\` as prose, then one \`##\` per scenario holding \`- **Name**: rule\` items with their edge cases nested as \`  - **Name**: ...\`, then \`## ${QUESTIONS_SECTION}\` with \`- **Name**: question\` items. Nothing else.`,
257	  ].join('\n')
258	}
